Translate("ptBR", "dun-morogh", {
	title = "Dun Morogh",
	sections = {
		{
			title = "Resumo",
			text = [=[Dun Morogh é uma terra de neve e pedra no oeste de Khaz Modan, a antiga pátria dos {link:dwarves}anões{/link}. Seus picos são os mais altos dos {link:eastern-kingdoms}Reinos do Leste{/link}, e dentro do maior deles fica {link:ironforge}Altaforja{/link}, a capital do {link:kingdom-of-ironforge}Reino de Altaforja{/link}. Os {link:gnomes}gnomos{/link} também viveram aqui, na cidade de {link:gnomeregan}Gnomeregan{/link}, sob as colinas do oeste. Entre as duas cidades há lagos congelados, bosques de pinheiros e uma única e longa estrada através da neve. É uma terra dura, e seu povo se orgulha dela.]=],
		},
		{
			title = "Origens",
			text = [=[Os anões dizem que foram moldados da pedra destas montanhas em eras passadas, e que {link:ironforge}Altaforja{/link} é seu lar mais antigo. Há muito tempo, todos os anões eram governados dali por um único grande rei. Quando esse rei morreu, os clãs Barbabronze, Martelo Feroz e {link:dark-iron-dwarves}Ferro Negro{/link} guerrearam por seu trono, e os Barbabronze ficaram com a montanha. Os gnomos se tornaram vizinhos e amigos dos anões, e ergueram {link:gnomeregan}Gnomeregan{/link} nos contrafortes do oeste. Nenhuma crônica registra o ano em que qualquer das duas cidades foi fundada.]=],
		},
		{
			title = "Os Dias de Hoje",
			text = [=[Dun Morogh está menos segura do que em qualquer tempo de que se tenha lembrança. Grande parte do exército do rei está longe, servindo à {link:alliance}Aliança{/link} em terras estrangeiras, e os montanhistas que ficaram são poucos. Os {link:troggs}troggs{/link} brotaram dos lugares profundos e agora ocupam o Caminho de {link:coldridge-valley}Cristálgida{/link} e as cavas da {link:gol-bolar-quarry}Pedreira Gol'Bolar{/link}. Os {link:frostmane-trolls}trolls Jubafria{/link} ocupam suas cavernas e serras no oeste. {link:gnomeregan}Gnomeregan{/link} está perdida, e seu povo envenenado vagueia diante de seus portões. Wendigos tomaram o {link:the-grizzled-den}Covil Cinzento{/link}. O mais preocupante de tudo: espiões do {link:dark-iron-dwarves}clã Ferro Negro{/link} foram vistos no leste, levando mapas de túneis que passam por baixo da própria {link:ironforge}Altaforja{/link}.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os anões de {link:ironforge}Altaforja{/link}.{/b} Mineiros, cervejeiros, criadores de carneiros e montanhistas, vivem em {link:kharanos}Kharanos{/link}, na {link:brewnall-village}Aldeia da Cevada{/link} e nos acampamentos solitários das terras altas.
• {b}Os gnomos de {link:gnomeregan}Gnomeregan{/link}.{/b} Os sobreviventes de sua cidade caída se abrigam em Altaforja, e alguns trabalham em Kharanos para desfazer o mal que foi feito.
• {b}Os {link:frostmane-trolls}trolls Jubafria{/link}.{/b} Ocupam cavernas e serras no oeste e disputam as neves com os anões.
• {b}Os troggs.{/b} Os troggs Rockjaw subiram de debaixo da terra e agora atacam onde quer que os anões cavem.
• {b}Os wendigos e as feras.{/b} Wendigos, ursos, javalis e leopardos-das-neves percorrem as colinas, e alguns deles ficaram ousados demais e grandes demais.
• {b}Os {link:dark-iron-dwarves}Ferro Negro{/link}.{/b} Um bando deles ocupa o {link:ironband-s-compound}Complexo de Bandaferro{/link}, no leste, vigiando e esperando.]=],
		},
		{
			title = "História",
			text = [=[• {b}Os Três Martelos.{/b} Na guerra dos três clãs, os Barbabronze mantiveram {link:ironforge}Altaforja{/link} e expulsaram seus rivais. Um tratado guardado sob a cidade registra que os Martelo Feroz assinaram a paz, e os {link:dark-iron-dwarves}Ferro Negro{/link} não.
• {b}A {link:second-war}Segunda Guerra{/link}.{/b} Quando a {link:horde}Horda{/link} invadiu Khaz Modan, a própria Altaforja resistiu. Os anões se juntaram à {link:alliance}Aliança de Lordaeron{/link} e lutaram ao lado da humanidade até que a Horda fosse derrotada.
• {b}A Queda de {link:gnomeregan}Gnomeregan{/link}.{/b} Os troggs subiram sob a cidade gnômica. Os gnomos lutaram para expulsá-los, mas a arma que usaram envenenou a cidade e muitos dos seus. Os sobreviventes fugiram para Altaforja.
• {b}Os Dias de Hoje.{/b} Agora os anões enfrentam troggs, trolls e Ferro Negro ao mesmo tempo, com metade de suas forças longe, na guerra.]=],
		},
		{
			title = "Saber das Montanhas",
			text = [=[• Os Thunderbrew de {link:kharanos}Kharanos{/link} e os Barleybrew da {link:brewnall-village}Aldeia da Cevada{/link} são famílias rivais de cervejeiros. Cada uma acredita que a cerveja da outra só serve para javalis.
• Os {link:frostmane-trolls}trolls Jubafria{/link} cultivam uma erva pálida chamada erva-cintilante nas serras acima do {link:iceflow-lake}Lago Nevado{/link}, e a usam em seus rituais. Os anões encontraram um uso melhor para ela: cerveja escura.
• Os montanhistas de {link:ironforge}Altaforja{/link} entalham seus nomes nas coronhas de seus rifles, para que a neve possa ser levada a dizer quem ela levou.
• Ladrões em Altaforja sussurram que os tanques a vapor blindados do rei levam minério e gemas da {link:gol-bolar-quarry}Pedreira Gol'Bolar{/link} por um caminho estranhamente tortuoso, e que alguém deveria aliviá-lo de um pouco disso.]=],
		},
	},
})

Translate("ptBR", "coldridge-valley", {
	title = "Vale Cristálgida",
	aliases = { "Cristálgida" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale Cristálgida é um vale abrigado no sudoeste de {link:dun-morogh}Dun Morogh{/link}, cercado de montanhas por todos os lados. Novos defensores de {link:ironforge}Altaforja{/link} vêm aqui aprender seu ofício em Sidermar. O vale perdeu a paz. {link:troggs}Troggs{/link} Rockjaw invadiram o acampamento a oeste e infestam as colinas junto ao lago congelado. {link:frostmane-trolls}Trolls Jubafria{/link} ocupam uma caverna no sul. A única saída, pelo túnel do Caminho de Cristálgida, agora está cheia de troggs, e um montanhista vigia sua entrada.]=],
		},
	},
})

Translate("ptBR", "anvilmar", {
	title = "Sidermar",
	sections = {
		{
			title = "Resumo",
			text = [=[Sidermar é uma morada escavada fundo na encosta da montanha, na cabeceira do {link:coldridge-valley}Vale Cristálgida{/link}. Ali os instrutores de {link:ironforge}Altaforja{/link} ensinam os jovens a lutar, a orar e a exercer seu ofício, e os fornecedores lhes dão roupas quentes contra o frio. É também um refúgio. {link:gnomes}Gnomos{/link} que fugiram do veneno de {link:gnomeregan}Gnomeregan{/link} encontraram abrigo em seus salões, e alguns ainda contam o que perderam na estrada.]=],
		},
	},
})

Translate("ptBR", "kharanos", {
	title = "Kharanos",
	aliases = { "Destilaria Cervaforte" },
	sections = {
		{
			title = "Resumo",
			text = [=[Kharanos é a principal cidade de {link:dun-morogh}Dun Morogh{/link}, um conjunto de casas de pedra na estrada entre {link:coldridge-valley}Cristálgida{/link} e {link:ironforge}Altaforja{/link}. Em seu coração fica a Destilaria Cervaforte, famosa em toda Khaz Modan, cujas adegas estão abarrotadas de barris de Cerveja Trovão. A estalagem lá dentro raramente fica quieta. Montanhistas se apresentam aqui, e {link:senir-whitebeard}Senir Whitebeard{/link} escreve seus relatórios para o Senado de Altaforja. Dois gnomos da cidade trabalham numa máquina que esperam que cure seu povo.]=],
		},
	},
})

Translate("ptBR", "steelgrill-s-depot", {
	title = "Garagem do Gradaço",
	sections = {
		{
			title = "Resumo",
			text = [=[A Garagem do Gradaço fica logo a nordeste de {link:kharanos}Kharanos{/link}. É a oficina de {link:beldin-steelgrill}Beldin Steelgrill{/link}, o melhor mecânico de máquinas de cerco das montanhas, e um reduto dos pilotos da Brigada de Cerco. Seus tanques a vapor blindados têm nomes como Jetsteam e Trollplow, e seus pilotos se gabam deles como outros anões se gabam de carneiros. A garagem ouve muito do que se passa nas estradas, e foi o relato de um montanhista aqui que primeiro chamou a atenção para uma estranha fogueira acima de {link:gol-bolar-quarry}Gol'Bolar{/link}.]=],
		},
	},
})

Translate("ptBR", "the-grizzled-den", {
	title = "Covil Cinzento",
	sections = {
		{
			title = "Resumo",
			text = [=[O Covil Cinzento é uma caverna nas colinas a oeste de {link:kharanos}Kharanos{/link}. Seus túneis já foram uma rica fonte de minério, e os mineiros de Kharanos trabalhavam ali. Então os wendigos se espalharam de suas próprias cavernas e a tomaram. Os mineiros fugiram e deixaram seus carregamentos para trás. Um montanhista chamado Cornelius entrou para descobrir quão ruim estava a situação e nunca mais saiu. Lá no fundo vive um wendigo barulhento e selvagem chamado Frosthowl.]=],
		},
	},
})

Translate("ptBR", "chill-breeze-valley", {
	title = "Vale Brisa Álgida",
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale Brisa Álgida se abre no oeste de {link:dun-morogh}Dun Morogh{/link}, entre {link:kharanos}Kharanos{/link} e as colinas de {link:gnomeregan}Gnomeregan{/link}. Sua parte leste é muito percorrida, pois a estrada que vem do Caminho de {link:coldridge-valley}Cristálgida{/link} passa por ela. Poucos vão de bom grado a seus cantos mais quietos. Ali, um grande wendigo chamado Old Icebeard ocupa uma caverna, e certa vez levou toda a despensa de carne do caçador Tundra MacGrann, que acampa por perto com uma perna ruim e a barriga vazia.]=],
		},
	},
})

Translate("ptBR", "brewnall-village", {
	title = "Aldeia da Cevada",
	aliases = { "Cevada" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Aldeia da Cevada fica na margem oeste do {link:iceflow-lake}Lago Nevado{/link}. É o lar da família Barleybrew, cervejeiros que experimentam sem medo e às vezes sem sucesso. Seu Evershine arde tão forte que os pilotos de cerco o despejam em suas fornalhas. Os Barleybrew não têm nenhum apreço pelos Thunderbrew de {link:kharanos}Kharanos{/link}, e não se furtam a uma pequena travessura na adega dos rivais. Pescadores trabalham no lago ao lado deles, e os {link:frostmane-trolls}trolls Jubafria{/link} observam do sudoeste.]=],
		},
	},
})

Translate("ptBR", "iceflow-lake", {
	title = "Lago Nevado",
	sections = {
		{
			title = "Resumo",
			text = [=[O Lago Nevado se estende pelo norte de {link:dun-morogh}Dun Morogh{/link}, a oeste de {link:ironforge}Altaforja{/link}, congelado durante boa parte do ano. Um rio de gelo desce até ele a partir da ponte ao norte de {link:kharanos}Kharanos{/link}. Lobos caçam na ilha em seu centro. Os pescadores da {link:brewnall-village}Aldeia da Cevada{/link} abrem buracos no gelo e esperam dias sobre suas linhas, e amaldiçoam os wendigos que roubam o pouco que pescam.]=],
		},
	},
})

Translate("ptBR", "frostmane-hold", {
	title = "Fortaleza Jubafria",
	sections = {
		{
			title = "Resumo",
			text = [=[A Fortaleza Jubafria é a grande caverna dos {link:frostmane-trolls}trolls Jubafria{/link}, a sudoeste da {link:brewnall-village}Aldeia da Cevada{/link}. Caçadores de cabeças, esfoladores, andarilhos-da-neve e lançadores de sombras vivem ali em número que assustou até o {link:dwarves}anão{/link} enviado para contá-los. A Fortaleza é o coração do poder Jubafria em {link:dun-morogh}Dun Morogh{/link}. Os anões tentaram descobrir o que os trolls planejam lá dentro, e seus relatórios causaram tanto problema no Senado quanto na neve.]=],
		},
	},
})

Translate("ptBR", "shimmer-ridge", {
	title = "Cordilheira Cintilante",
	sections = {
		{
			title = "Resumo",
			text = [=[A Cordilheira Cintilante é uma cadeia de colinas altas no norte de {link:dun-morogh}Dun Morogh{/link}, perto do {link:iceflow-lake}Lago Nevado{/link} e a oeste dos Portões de {link:ironforge}Altaforja{/link}. Os {link:frostmane-trolls}trolls Jubafria{/link} mantêm acampamentos sobre ela, ligados por uma ponte, e seus videntes cuidam ali de cestos de erva-cintilante. A erva tem algum papel em seus ritos. Para os cervejeiros da {link:brewnall-village}Aldeia da Cevada{/link} ela tem outra serventia, e eles pagam bem a quem subir a cordilheira para roubá-la.]=],
		},
	},
})

Translate("ptBR", "gates-of-gnomeregan", {
	title = "Portões de Gnomeregan",
	sections = {
		{
			title = "Resumo",
			text = [=[Ao norte da {link:brewnall-village}Aldeia da Cevada{/link}, as colinas do oeste de {link:dun-morogh}Dun Morogh{/link} sobem até os portões de {link:gnomeregan}Gnomeregan{/link}. Esta já foi uma terra movimentada de máquinas e aldeias gnômicas. Agora as bombas e os filtros estão quebrados, e os gnomos que restam estão envenenados, doentes e hostis, vagando diante das portas da cidade que não conseguiram salvar. Entre eles se esconde, disfarçado, um espião {link:dwarves}anão{/link} de intenções duvidosas. {link:gnomes}Gnomos{/link} que fugiram dizem que registros preciosos de seu povo ainda jazem enterrados na neve aqui.]=],
		},
	},
})

Translate("ptBR", "gol-bolar-quarry", {
	title = "Pedreira Gol'Bolar",
	aliases = { "Gol'Bolar" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Pedreira Gol'Bolar é uma grande cava a céu aberto no leste de {link:dun-morogh}Dun Morogh{/link}, onde os mineiros do rei cortam minério e pedra. Quando cavaram fundo, os troggs Rockjaw jorraram da rocha, destroçaram as máquinas e expulsaram os mineiros da cava. Agora o capataz se enfurece, um senador de {link:ironforge}Altaforja{/link} paga por cabeças de troggs, e o mestre da pedreira espera que ninguém descubra que os troggs levaram sua pólvora de detonação. Dos Montes Túndricos, acima, um forasteiro Martelo Feroz vigia tudo.]=],
		},
	},
})

Translate("ptBR", "amberstill-ranch", {
	title = "Rancho Ambarmanso",
	sections = {
		{
			title = "Resumo",
			text = [=[O Rancho Ambarmanso fica junto à estrada, a leste de {link:kharanos}Kharanos{/link}. A família Amberstill cria os grandes carneiros montanheses que carregam os anões de {link:ironforge}Altaforja{/link}, e seus rebanhos são o orgulho de {link:dun-morogh}Dun Morogh{/link}. Os carneiros do rancho agora seguem para a expedição em {link:alterac-mountains}Alterac{/link}, e precisam de selas das melhores peles de leopardo. O rebanho também encontrou um caçador próprio: a fera {link:vagash}Vagash{/link}, que tem seu covil nas encostas acima e desce à noite.]=],
		},
	},
})

Translate("ptBR", "misty-pine-refuge", {
	title = "Refúgio Pinhal das Brumas",
	sections = {
		{
			title = "Resumo",
			text = [=[{link:the-harborage}O Refúgio{/link} Pinhal das Brumas é uma casa solitária nas colinas do norte de {link:dun-morogh}Dun Morogh{/link}, a leste dos Portões de {link:ironforge}Altaforja{/link}. O {link:father-gavin}Padre Gavin{/link}, da {link:argent-dawn}Aurora Argêntea{/link}, a restaurou e mantém sua lareira acesa para qualquer viajante surpreendido pelo frio. As montanhas ao redor se tornaram perigosas. Um deslizamento de pedras dos picos despertou espíritos de gelo, e o maior deles parece trazer tempestades e novos deslizamentos aonde quer que vá.]=],
		},
	},
})

Translate("ptBR", "helm-s-bed-lake", {
	title = "Lago Helm",
	sections = {
		{
			title = "Resumo",
			text = [=[O Lago Helm fica no extremo sudeste de {link:dun-morogh}Dun Morogh{/link}, perto das passagens para {link:loch-modan}Loch Modan{/link}. Sua água está quase toda congelada, e a região ao redor é selvagem e vazia. {link:troggs}Troggs{/link} Rockjaw percorrem suas margens. Nas colinas ao norte, um piloto de cerco espera ao lado de duas máquinas por um amigo que seguiu sozinho em busca de minério raro. O amigo era Mori Hildelve, e um grande urso chamado Mangeclaw o encontrou primeiro.]=],
		},
	},
})

Translate("ptBR", "ironband-s-compound", {
	title = "Complexo de Bandaferro",
	sections = {
		{
			title = "Resumo",
			text = [=[O Complexo de Bandaferro é uma casa com pátio ao sul do {link:helm-s-bed-lake}Lago Helm{/link}, no leste de {link:dun-morogh}Dun Morogh{/link}. Seus donos anões o abandonaram. {link:dark-iron-dwarves}Anões Ferro Negro{/link} o ocupam agora, liderados por um capitão chamado Beld, e atacam qualquer um que se aproxime. O {link:earthseer-farsen}Vidente da Terra Farsen{/link}, um Martelo Feroz, acredita que não são meros saqueadores. Mapas tirados de seus mortos mostram túneis que correm fundo sob a terra e se encontram debaixo de {link:ironforge}Altaforja{/link}.]=],
		},
	},
})

Translate("ptBR", "frostmane-trolls", {
	title = "Trolls Jubafria",
	aliases = { "Jubafria", "trolls Jubafria", "tribo Jubafria" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Jubafria são uma tribo de {link:trolls}trolls{/link} que vive nas neves de {link:dun-morogh}Dun Morogh{/link}. São ferozes e reservados, e disputam estas montanhas com os anões. Nenhuma crônica registra quando chegaram aqui.]=],
		},
		{
			title = "Suas Terras",
			text = [=[Sua maior fortaleza é a {link:frostmane-hold}Fortaleza Jubafria{/link}, uma caverna a sudoeste da {link:brewnall-village}Aldeia da Cevada{/link}. Também mantêm acampamentos na {link:shimmer-ridge}Cordilheira Cintilante{/link} e uma caverna no sul do {link:coldridge-valley}Vale Cristálgida{/link}, onde vivem os filhotes da tribo. Seus guerreiros são caçadores de cabeças e andarilhos-da-neve. Seus videntes e lançadores de sombras praticam uma magia própria, e colhem erva-cintilante para seus rituais.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[O Senado de {link:ironforge}Altaforja{/link} já tem trabalho de sobra com os troggs, e preferiria nem pensar nos trolls. Dois irmãos da família Whitebeard foram enviados para descobrir quão grande é de fato a ameaça. {link:grelin-whitebeard}Grelin{/link} julgou que os trolls de {link:coldridge-valley}Cristálgida{/link} eram poucos. {link:senir-whitebeard}Senir{/link} encontrou a {link:frostmane-hold}Fortaleza Jubafria{/link} cheia deles. Entre os dois relatórios fica a questão de quanto os anões podem se dar ao luxo de ignorar. Em Cristálgida, um troll chamado {link:grik-nir-the-cold}Grik'nir, o Frio{/link}, roubou mais que um diário dos anões: mostrou-lhes que os Jubafria estão vigiando.]=],
		},
	},
})

Translate("ptBR", "gnomeregan-exiles", {
	title = "Exilados de Gnomeregan",
	aliases = { "exilados de Gnomeregan" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Exilados de Gnomeregan são os gnomos que sobreviveram à queda de sua cidade. São um povo sem lar. A maioria vive em {link:ironforge}Altaforja{/link}, onde o Rei {link:magni-bronzebeard}Magni Bronzebeard{/link} lhes deu lugar em {link:tinker-town}Tinker Town{/link}, mas estão espalhados por {link:dun-morogh}Dun Morogh{/link} e além.]=],
		},
		{
			title = "Depois da Queda",
			text = [=[Os troggs subiram sob {link:gnomeregan}Gnomeregan{/link}, e os gnomos os repeliram com uma arma de sua própria invenção. Deu terrivelmente errado. A cidade foi envenenada, e muitos de seus habitantes foram transformados em leprosos doentes e sem juízo que ainda vagueiam diante de seus portões. Os demais fugiram para a neve com o que puderam carregar. Alguns perderam tudo para os trolls no caminho. Outros deixaram para trás os registros de suas famílias, de suas invenções e de seu ofício.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Os exilados não desistiram. Em {link:kharanos}Kharanos{/link}, {link:razzle-sprysprocket}Razzle Sprysprocket{/link} e Ozzie Togglevolt constroem uma máquina que esperam restaurar os gnomos envenenados. Em {link:ironforge}Altaforja{/link}, os engenhoqueiros de {link:gnomeregan}Gnomeregan{/link} mandam forasteiros corajosos de volta à cidade para resgatar seu saber perdido. O Alto Engenhoqueiro {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} jura que seu povo retomará o lar das mãos do traidor que o ocupa.]=],
		},
	},
})

Translate("ptBR", "sten-stoutarm", {
	title = "Sten Stoutarm",
	subtitle = "Fornecedor de Cristálgida",
	found = "Diante das portas de Sidermar",
	hint = [=[Fale com o anão que recebe os recém-chegados às portas de Sidermar.]=],
	allegiance = "Reino de Altaforja",
	aliases = { "Stoutarm" },
	sections = {
		{
			title = "Resumo",
